(function(){"use strict";self.onmessage=async c=>{const{id:s,bitmap:t,quality:o}=c.data||{};try{const e=new OffscreenCanvas(t.width,t.height);e.getContext("2d").drawImage(t,0,0),t.close();const a=await(await e.convertToBlob({type:"image/jpeg",quality:o})).arrayBuffer();self.postMessage({id:s,buf:a},[a])}catch(e){try{t?.close?.()}catch{}self.postMessage({id:s,fout:String(e?.message||e)})}}})();
